// Release builds are signed with the owner's key from signing/ (see docs/dev/SIGNING.md). android/
// is regenerated by prebuild, so the signing config is injected here instead of hand-edited.
// The keystore and its password file are gitignored; without them (a fresh clone) release builds
// fall back to the debug key so the project still builds — such an APK must not be distributed.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// chaat: release signing';

const SIGNING_CONFIG = `
        ${MARKER}
        release {
            def ksProps = new Properties()
            def ksFile = rootProject.file('../signing/keystore.properties')
            if (ksFile.exists()) ksFile.withInputStream { ksProps.load(it) }
            storeFile rootProject.file('../signing/release.p12')
            storeType 'PKCS12'
            storePassword ksProps.getProperty('storePassword')
            keyAlias 'release'
            keyPassword ksProps.getProperty('storePassword')
        }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents;
    if (gradle.includes(MARKER)) return cfg;

    const signingConfigs = /signingConfigs \{\n/;
    const releaseUsesDebug = /(release \{[\s\S]*?)signingConfig signingConfigs\.debug/;
    if (!signingConfigs.test(gradle) || !releaseUsesDebug.test(gradle)) {
      throw new Error('with-release-signing: app/build.gradle layout changed; update the plugin');
    }
    // buildTypes first: before the signing block is added, the only `release {` is the build type.
    gradle = gradle.replace(
      releaseUsesDebug,
      "$1signingConfig rootProject.file('../signing/release.p12').exists() ? signingConfigs.release : signingConfigs.debug",
    );
    gradle = gradle.replace(signingConfigs, (m) => m + SIGNING_CONFIG.slice(1) + '\n');
    cfg.modResults.contents = gradle;
    return cfg;
  });
};
